      "scope": "Half day",
      "bestSeason": "Dry-season conditions are generally more comfortable for walking, but Bali’s wet season can bring lush scenery and sudden rain.",
      "pace": "Balanced, with a rural transfer, an easy-paced terrace walk and time for a meal.",
      "themes": [
        "Culture",
        "Food"
      ]
    },
    "routeSummary": "Travel north from Ubud through village landscapes, explore the rice terraces and irrigation paths, then return toward central Ubud for a local meal.",
    "highlights": [
      {
        "icon": "🌾",
        "title": "Layered rice-field landscapes",
        "note": "Take time to appreciate the terraces, paths and surrounding countryside rather than treating the area as a quick photo stop."
      },
      {
        "icon": "🛺",
        "title": "Village connections",
        "note": "The route links Ubud with its rural setting, offering context for the relationship between agriculture, landscape and local life."
      },
      {
        "icon": "🍽️",
        "title": "Balinese flavors",
        "note": "Finish with a local meal that provides a grounded introduction to regional tastes and a chance to reflect on the morning."
      }
    ]
  },
  "practical": {
    "included": [
      "A half-day route outline combining rural sightseeing and a local meal stop.",
      "Guidance for a terrace walk and the transfer between the countryside and Ubud."
    ],
    "notIncluded": [
      "Transport arrangements, meal costs and personal expenses are not specified and should be confirmed separately.",
      "Any activities or services beyond the stated route."
    ],
    "whatToBring": [
      "Comfortable walking shoes with good grip.",
      "Sun protection, drinking water and light rain protection.",
      "A small bag for personal essentials."
    ],
    "localTips": [
      {
        "topic": "Walking conditions",
        "note": "Paths around rice fields can be uneven, narrow or slippery after rain. Take a steady pace and follow local access guidance."
      },
      {
        "topic": "Respect for the landscape",
        "note": "Stay on appropriate paths, avoid entering working fields without permission and be considerate of residents and farmers."
      },
      {
        "topic": "Meal preferences",
        "note": "Tell the eatery about dietary needs or allergies before ordering, and carry any essential medication with you."
      }
    ],
    "healthSafety": "Heat, humidity and sudden rain can affect comfort. Drink water regularly, use sun protection and allow extra care on uneven paths. Seek local medical assistance if you feel unwell.",
    "emergencyContacts": [
      {
        "label": "Trip support",
        "value": "qa@example.com"
      },
      {
        "label": "Local emergency assistance",
        "value": "Ask your driver, accommodation or a nearby local authority for the current emergency contact."
      }
    ]
  },
  "closing": {
    "closingNote": "This half-day route offers a gentle balance of countryside, culture and food, with enough flexibility to enjoy the landscape at an unhurried pace.",
    "disclaimer": "Route conditions, weather, access and local services can change. Confirm transport, meal arrangements and any access requirements locally before setting out."
  }
}

